"use client";
/* Onigiri, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Onigiri(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("onigiri"); }, []);
  return React.createElement("piix-sprite", { "name": "onigiri", ...piixAttrs(props) });
}

export default Onigiri;
